.nias-notif-downloadbox:before{border-bottom-left-radius:15px;left:0;}
.nias-notif-downloadbox:after{border-bottom-right-radius:15px;right:0;}
.nias-doenload-title-loop a{display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden;}
.site-header{padding-inline-end:0px;padding-inline-start:0px;}
.ns-fx-cursor{position:fixed;inset:0;z-index:2147483000;pointer-events:none;opacity:1;transition:opacity 0.25s ease;}
.ns-fx-cursor.is-hidden{opacity:0;}
.ns-fx-cursor[data-blend]{mix-blend-mode:difference;}
.ns-fx-ring{position:fixed;top:0;left:0;width:36px;height:36px;border:1.5px solid #004cff;border-radius:50%;transition:opacity 0.25s ease,background-color 0.25s ease;will-change:transform;}
.ns-fx-cursor.is-hover .ns-fx-ring{background-color:color-mix(in srgb,#004cff 12%,transparent);}
.ns-fx-cursor[data-style="dot"] .ns-fx-dot{width:calc(36px * 0.45);height:calc(36px * 0.45);opacity:.85;}
.ns-fx-cursor[data-style="glow"] .ns-fx-ring{border:0;background:radial-gradient(circle,#004cff 0%,transparent 70%);filter:blur(6px);opacity:.6;}
.ns-fx-cursor[data-style="glow"].is-hover .ns-fx-ring{opacity:.9;}
@media (pointer:coarse){.ns-fx-cursor{display:none;}}
video.entered.nias-theme-sp__preview-video{aspect-ratio:16/9 !important;object-fit:cover;max-width:100%;}
